script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        params: { ...api.context.props,
            table: event.payload.item.id
        }
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        params: { ...api.context.props,
            sysId: event.payload.item.id,
            selectedPlaybook: null,
            selectedStage: null,
            selectedActivity: null
        }
    };
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	return {
		params: { ...api.context.props,
            experience: event.payload.item.id
        }
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({ api, event }) {
	return {
        params: { ...api.context.props,
            compact: event.payload.value
        }
    };
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	const playbookExperienceId = api.context.props.experience || '';
	const url = '/nav_to.do?uri=sys_playbook_experience.do?sys_id=' + playbookExperienceId;

	return playbookExperienceId ? url : '';
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	return {
		params: {
			...api.context.props,
			...event.payload
		}
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	return {
		items: [{
			type: 'html',
			message: `<b>Preview Record</b> ${event.payload.sys_id} ${event.payload.table} record will be displayed to the user.`
		}]
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	return {
		params: {
			...api.context.props,
			...event.payload,
			selectedPlaybook: null,
            selectedStage: null,
            selectedActivity: null
		}
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	const queryString = 'sys_idSTARTSWITH' + event.payload.sysId;
	return {
		propName: 'parent_record_look_up',
		value: queryString
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	return {
		items: [{
			type: 'info',
			message: '<b>Preview Record</b> The selected record will be displayed to the user.'
		}]
	};
}
